-- PinWith 공식 계정(@pinwith) 리스트(en2). 이미 있으면 건너뛴다. 장소 id·좌표는 구글 장소 검색 결과(2026-10-17).
do $seed$
declare
  o uuid := (select id from public.profiles where handle = 'pinwith');
  doc jsonb := $json$[{"slug":"paris-3-days","title":"Paris in 3 Days: The Classics, Without the Stress","desc":"A first visit to Paris that hits the big names but leaves room to sit in a café. Day 1 is the Left Bank and the Eiffel Tower, Day 2 is the islands and the Marais, Day 3 is the Louvre and Montmartre.\nBook timed tickets for the Louvre, the Eiffel Tower and Sainte-Chapelle before you go.","kind":"course","themes":["Paris","France","First trip","3 days"],"sections":[{"name":"Day 1 · Left Bank & the Tower","items":[["ChIJG5Qwtitu5kcR2CNEsYy9cdA",48.8599614,2.3265614,"Musée d'Orsay","Impressionists in a former railway station. Go straight to the top floor for Monet and Van Gogh, then work your way down. Closed Mondays; open late on Thursdays.",["Closed Mon","Book ahead"]],["ChIJU-XFaSdw5kcReNgoNaOVGe8",48.856669,2.306326,"Rue Cler (Café du Marché)","A pedestrian market street near the tower. Pick up cheese, bread and fruit for a picnic, or sit down at the café.",["Picnic"]],["ChIJLU7jZClu5kcR4PcOOO6p3I0",48.8583701,2.2944813,"Eiffel Tower","Book the elevator online well ahead. After dark the tower sparkles for a few minutes at the top of every hour.",["Book ahead","Night"]],["ChIJpSFnZvtv5kcRlSMne7c0v40",48.8627982,2.2876042,"Trocadéro","The classic full-length view of the tower across the river.",["Photo spot"]]]},{"name":"Day 2 · The islands & the Marais","items":[["ChIJATr1n-Fx5kcRjQb6q6cdQDY",48.8529682,2.3499021,"Notre-Dame de Paris","Reopened after the restoration. Entry is free; you can reserve a time slot to skip most of the line.",["Free"]],["ChIJR3122B9u5kcRaCck3PlB9DM",48.855375,2.3449609,"Sainte-Chapelle","Walls made almost entirely of stained glass. Go on a sunny morning and book a slot.",["Book ahead"]],["ChIJUeiI4P9x5kcRqEwHl6V32GQ",48.8556114,2.3655266,"Place des Vosges","The oldest planned square in Paris. Grab a falafel in the Marais and eat it on the lawn.",["Free","Picnic"]]]},{"name":"Day 3 · Louvre & Montmartre","items":[["ChIJD3uTd9hx5kcR1IQvGfr8dbk",48.8606111,2.337644,"Louvre Museum","Pick three or four rooms instead of trying to see everything. Closed Tuesdays; book a morning slot.",["Closed Tue","Book ahead"]],["ChIJe2jeNttx5kcRi_mJsGHdkQc",48.8466144,2.3363309,"Jardin du Luxembourg","Green chairs, toy sailboats on the pond and a slow hour in the afternoon.",["Free"]],["ChIJ442GNENu5kcRGYUrvgqHw88",48.8867046,2.3431043,"Sacré-Cœur, Montmartre","Free basilica at the top of the hill with a view over the city. Watch your bag on the steps.",["Free","Sunset"]]]}]},{"slug":"vlog-utah-mighty-5","title":"VLOG · Utah's Mighty 5 Road Trip (+ Monument Valley & Horseshoe Bend)","desc":"Written like a road-trip vlog: every section is an episode and the notes read like a shot list. Plan about 7–9 days and around 1,000 miles of driving, starting and ending in Las Vegas or Salt Lake City.\nPinWith lets each stop link to a timestamp in your YouTube video — if you film this, attach your own moments to each place.","kind":"course","themes":["Utah","Road trip","National parks","Vlog","USA"],"sections":[{"name":"Ep.1 · Zion","items":[["ChIJRwqsNb3CyoARTXWdRUweYI4",37.2000925,-112.9869847,"Zion Canyon Visitor Center","▶ Cold open: shuttle doors open, canyon walls fill the frame. Parking fills by early morning — arrive before 7.",["Early","Shuttle"]],["ChIJNSJNzxHDyoARTS4jS6o3MKY",37.2592428,-112.9512609,"Angels Landing","▶ The chains section. Hiking past Scout Lookout needs a permit from the lottery — no permit, film the view from the lookout instead.",["Permit","Exposure"]]]},{"name":"Ep.2 · Bryce & the scenic drive","items":[["ChIJven5sRhpNYcRtsYVn2bjBCE",37.6233516,-112.1672079,"Bryce Canyon (Sunset Point)","▶ Time-lapse the hoodoos at golden hour, then hike down the Navajo Loop. It's above 8,000 ft — slow down and drink water.",["Sunrise/sunset","Altitude"]],["ChIJIw-BhQkZSocRncIWG0YMLJU",38.2914608,-111.262042,"Capitol Reef National Park","▶ Quiet episode: orchards, petroglyphs and the scenic drive. The least crowded of the five.",["Quiet"]]]},{"name":"Ep.3 · Moab: Arches & Canyonlands","items":[["ChIJVfkzzzjZR4cRED_Jagrg_-M",38.7436297,-109.4993124,"Delicate Arch","▶ The money shot. About 3 miles round trip with no shade — go at sunrise or sunset, bring plenty of water. Arches may require a timed-entry reservation in busy months.",["Water","Reservation"]],["ChIJWUIfgYQZSIcRC95Xzjbxxa4",38.3885359,-109.8658021,"Mesa Arch (Canyonlands)","▶ Sunrise glow under the arch. Short walk, big crowd of tripods — get there early.",["Sunrise"]],["ChIJmWMPEXUSSIcRTLkqeG0ZK-4",38.5054267,-109.7294241,"Dead Horse Point State Park","▶ Drone-free zone? Check the rules. The river gooseneck view is the episode thumbnail.",["Views"]]]},{"name":"Ep.4 · Bonus: Arizona border","items":[["ChIJD17qc0MuN4cRKfifHiV975w",36.9820968,-110.1118615,"Monument Valley (Navajo Tribal Park)","▶ Tribal park with its own entry fee. The dirt loop is rough — high clearance helps. Respect the closed areas.",["Tribal park"]],["ChIJCWtWIo1sNIcRAhdPY4lwY0U",36.8768096,-111.5057449,"Horseshoe Bend","▶ Finale: walk out to the rim at sunset. No railing in most spots — keep back from the edge.",["Sunset"]]]}]},{"slug":"london-weekend","title":"London Weekend: Museums, Markets & a Free Skyline View","desc":"Two days, lots of free stuff. Many of London's big museums are free; the paid highlights are the Tower and Westminster Abbey.","kind":"course","themes":["London","UK","Weekend"],"sections":[{"name":"Saturday","items":[["ChIJG1YB2m4RdkgRsetv9D40NGY",51.5170002,-0.205847,"Portobello Road Market","Antiques and food stalls; Saturday is the full market day. Go in the morning.",["Saturday"]],["ChIJB9OTMDIbdkgRp0JWbQGZsS8",51.5194133,-0.1269566,"British Museum","Free. Rosetta Stone, the Parthenon sculptures and the Egyptian rooms.",["Free"]],["ChIJLzVDusQEdkgRelObBaL_jto",51.4993695,-0.1272993,"Westminster Abbey","Coronations, royal tombs and Poets' Corner. Book online; closed to visitors on Sundays except for services.",["Tickets"]]]},{"name":"Sunday","items":[["ChIJ3TgfM0kDdkgRZ2TV4d1Jv6g",51.5081124,-0.0759493,"Tower of London","See the Crown Jewels first thing before the queue builds, then join a Yeoman Warder tour.",["Early","Tickets"]],["ChIJD2bPdVcDdkgRuUSgnOXnKDE",51.5055826,-0.0904808,"Borough Market","Lunch: graze the stalls. Closed on Mondays.",["Closed Mon","Lunch"]],["ChIJgaI8bFIDdkgRhJJqLMxsFdU",51.5112422,-0.0835493,"Sky Garden","Free skyline views from a glass dome — but you need to book a free slot online, and they go fast.",["Free","Book ahead"]]]}]},{"slug":"rome-2-days","title":"Rome in 2 Days: Ancient Rome, the Vatican & Trastevere","desc":"Day 1 is ancient Rome on foot; Day 2 is the Vatican in the morning and Trastevere for dinner. Cover shoulders and knees for churches and the Vatican.","kind":"course","themes":["Rome","Italy","2 days"],"sections":[{"name":"Day 1 · Ancient Rome","items":[["ChIJrRMgU7ZhLxMRxAOFkC7I8Sg",41.8902102,12.4922309,"Colosseum","Timed tickets; the standard ticket also covers the Roman Forum and Palatine Hill.",["Book ahead"]],["ChIJ782pg7NhLxMR5n3swAdAkfo",41.8920906,12.4864378,"Roman Forum","Walk the old heart of the empire. Uneven ground — wear good shoes and bring water.",["Shoes"]],["ChIJqUCGZ09gLxMRLM42IPpl0co",41.8986108,12.4768729,"Pantheon","The 2,000-year-old dome with the open oculus. Now ticketed; buy online.",["Tickets"]],["ChIJ1UCDJ1NgLxMRtrsCzOHxdvY",41.9009325,12.483313,"Trevi Fountain","Come late at night or very early for photos without the crowd. Toss a coin over your shoulder.",["Night"]]]},{"name":"Day 2 · Vatican & Trastevere","items":[["ChIJKcGbg2NgLxMRthZkUqDs4M8",41.9064878,12.4536413,"Vatican Museums & Sistine Chapel","Book the earliest slot. Closed on most Sundays. Dress code applies.",["Book ahead","Dress code"]],["ChIJ921caWhgLxMRM_bfeCcgn6M",41.8848294,12.4704017,"Trastevere","Cobbled lanes and trattorias across the river. Cacio e pepe and supplì for dinner.",["Dinner"]]]}]},{"slug":"oahu-beaches-eats","title":"Oahu: Beaches, Hikes & Plate Lunches","desc":"Honolulu plus a day trip to the North Shore. Several spots now need advance reservations for visitors — check before you go.","kind":"collection","themes":["Hawaii","Oahu","Beach","USA"],"sections":[{"name":"Honolulu side","items":[["ChIJrynB5fRtAHwReIhoKsXdM0Y",21.2793462,-157.8291847,"Waikiki","Surf lessons on gentle waves and sunset on the beach.",["Beach"]],["ChIJmSAXAYlyAHwRUuIwMlELnkI",21.2637984,-157.8040943,"Diamond Head","Out-of-state visitors need a timed reservation. Go early; the summit trail is steep and sunny.",["Reservation","Early"]],["ChIJZdI0IQBmAHwRDpj15_sGy7k",21.2848746,-157.8133438,"Leonard's Bakery","Hot malasadas — try one plain and one filled (haupia is the island favourite).",["Snack"]],["ChIJv8OgpXMSAHwR-htdFp00cOI",21.2690358,-157.6937919,"Hanauma Bay","Snorkelling in a protected bay. Reservations required and released a couple of days ahead; closed some days of the week.",["Reservation"]],["ChIJM2ZQCUNvAHwRLGCcDaeSxbg",21.3675985,-157.938858,"Pearl Harbor National Memorial","USS Arizona Memorial boat tickets are free but limited — reserve online.",["Reserve"]]]},{"name":"Windward & North Shore","items":[["ChIJfy9okvgUAHwRseIWasniUOw",21.3925378,-157.7151208,"Lanikai Beach","Calm, clear water. No parking at the beach — park in Kailua and walk.",["Calm water"]],["ChIJeZG7TctYAHwRx_CZ3-LyTqI",21.5927614,-158.1034112,"Haleiwa Town","Surf town with shave ice and shops. Winter brings the big waves.",["Shave ice"]],["ChIJDbc-_eBPAHwRZtlcZ7AuohM",21.6773498,-157.9487037,"Giovanni's Shrimp Truck","Garlic shrimp plate with two scoops of rice. Expect a line.",["Lunch"]]]}]},{"slug":"mexico-city-food-culture","title":"Mexico City: Tacos, Murals & Museums in 3 Days","desc":"Centro Histórico, Chapultepec and Coyoacán — one area per day. Many museums close on Mondays.","kind":"course","themes":["Mexico City","Mexico","Food","Museums"],"sections":[{"name":"Day 1 · Centro Histórico","items":[["ChIJ_6pkSM3-0YURDDaRslwM_0w",19.432642,-99.1333215,"Zócalo","One of the world's biggest squares, ringed by the cathedral and the National Palace.",["Free"]],["ChIJs1uZdNP-0YUR7xEuCTGxAMM",19.4302794,-99.1387977,"Los Cocuyos","Tiny late-night taquería. Suadero and al pastor; point and order.",["Late night","Tacos"]]]},{"name":"Day 2 · Chapultepec","items":[["ChIJScjIILQB0oURJMVub-MaI4Q",19.4260032,-99.1862786,"Museo Nacional de Antropología","The Aztec Sun Stone and so much more — give it at least three hours. Closed Mondays.",["Closed Mon"]],["ChIJI4_tR83-0YURMouBJIUA4KY",19.4204397,-99.181935,"Chapultepec Castle","A walk uphill to a castle with city views. Closed Mondays.",["Closed Mon","Views"]]]},{"name":"Day 3 · Coyoacán","items":[["ChIJOz-6AMT_0YURofTM9_ekAWI",19.3551806,-99.1624636,"Frida Kahlo Museum (Casa Azul)","Tickets must be bought online in advance and sell out — book first, plan around it.",["Book ahead"]],["ChIJeYLOZMT_0YURFEhp2ubb43c",19.3527374,-99.1616374,"Mercado de Coyoacán","Tostadas, fresh juices and craft stalls a few blocks from Casa Azul.",["Lunch"]]]}]},{"slug":"barcelona-gaudi-tapas","title":"Barcelona: Gaudí, Tapas & the Beach","desc":"Two days of Gaudí in the morning, markets and tapas in the afternoon, the sea in the evening. Book Sagrada Família and Park Güell slots ahead.","kind":"course","themes":["Barcelona","Spain","Gaudí","Food"],"sections":[{"name":"Day 1 · Gaudí","items":[["ChIJk_s92NyipBIRUMnDG8Kq2Js",41.4036299,2.1743558,"Sagrada Família","Go when the sun hits the stained glass (late morning or afternoon). Timed tickets.",["Book ahead"]],["ChIJYUFLSe2ipBIRD04uni940kA",41.3917,2.164918,"Casa Batlló","Gaudí's dragon-scaled house on Passeig de Gràcia.",["Tickets"]],["ChIJq0HUUq6ipBIRWM6qGqALmok",41.4144948,2.1526945,"Park Güell","Mosaic terraces and city views. Timed entry to the monumental zone.",["Book ahead","Views"]]]},{"name":"Day 2 · Old town & the sea","items":[["ChIJg2xxlvmipBIRg1jhdSQR9hY",41.383962,2.1761991,"Barcelona Cathedral & Gothic Quarter","Get lost in the Gothic Quarter's lanes; the cathedral roof has a lift and a view.",["Old town"]],["ChIJAVoetfeipBIR1a1z3FTGCoY",41.3817399,2.1715853,"Mercat de la Boqueria","Fruit cups, jamón and a counter lunch. Go before noon; closed Sundays.",["Closed Sun"]],["ChIJJ5Y4CaijpBIR-2VJP9cOjh4",41.3783713,2.1924685,"Barceloneta Beach","End the day by the Mediterranean. Keep an eye on your phone and bag.",["Sunset"]]]}]}]$json$::jsonb;
  rec jsonb; sec jsonb; it jsonb; lid uuid; sid uuid; pos int; si int;
begin
  for rec in select * from jsonb_array_elements(doc) loop
    continue when exists (select 1 from public.lists where owner_id = o and slug = rec->>'slug');
    insert into public.lists (owner_id, slug, title, description, visibility, kind, themes, is_example)
    values (o, rec->>'slug', rec->>'title', rec->>'desc', 'public', (rec->>'kind')::public.list_kind,
            array(select jsonb_array_elements_text(rec->'themes')), true)
    returning id into lid;
    pos := 0; si := 0;
    for sec in select * from jsonb_array_elements(rec->'sections') loop
      sid := null;
      if sec->>'name' is not null then
        insert into public.sections (list_id, name, position) values (lid, sec->>'name', si) returning id into sid;
      end if;
      for it in select * from jsonb_array_elements(sec->'items') loop
        insert into public.places (google_place_id, lat, lng, coords_fetched_at)
        values (it->>0, (it->>1)::float8, (it->>2)::float8, now()) on conflict (google_place_id) do nothing;
        insert into public.list_items (list_id, section_id, place_id, position, added_by, custom_title, memo, tags)
        values (lid, sid, it->>0, pos, o, it->>3, it->>4, array(select jsonb_array_elements_text(it->5)));
        pos := pos + 1;
      end loop;
      si := si + 1;
    end loop;
  end loop;
end $seed$;
